import{_ as t,o as l,c as e,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"CDS Tentacle - Crimson","description":"","frontmatter":{"title":"CDS Tentacle - Crimson","date":"2024-08-22T00:00:00.000Z","updated":"2024-08-23T00:00:00.000Z","tags":["Ceph","Crimson","Squid","Storage Engine","Performance Optimization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/CDS_Tentacle_-_Crimson.md","filePath":"posts/2024/CDS_Tentacle_-_Crimson.md","lastUpdated":1780459816000}'),r={name:"posts/2024/CDS_Tentacle_-_Crimson.md"};function n(s,i,p,a,S,u){return l(),e("div",null,[...i[0]||(i[0]=[o("<p>CDS Tentacle - Crimson 会议纪要</p><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>会议地点</strong>： Google Meet</p><p><strong>参会人员</strong>： Squid 项目成员，包括 Squid 项目负责人、Intel 团队成员等。</p><p><strong>会议主题</strong>： Squid 项目进展、Crimson 存储引擎优化以及未来计划。</p><p><strong>会议内容</strong>：</p><p><strong>一、Squid 项目当前状态</strong></p><ul><li>Squid 已实现多核支持，包括 Reactor 和 Messenger。</li><li>支持 Blue Store、C Store 和 CN Store 作为后端，主要处理 RBD 工作负载。</li><li>支持通过 saadm 或重启快速部署集群。</li><li>提供初始的 Scrub 支持，可通过 SEF tell 命令启动 Scrub 或 Deep Scrub。</li><li>在恢复和备份方面进行了大量工作，提高了稳定性。</li><li>测试覆盖范围良好，拥有稳定的测试套件，并添加了恢复垃圾模式测试。</li><li>引入 SE Store 作为后端，大部分 API 测试和基本测试均通过。</li><li>引入协程，提高了代码友好性和开发效率。</li></ul><p><strong>二、Crimson 存储引擎优化</strong></p><ul><li>评估了 RBD 4K 随机读写性能，分析了扩展性。</li><li>优化了计算效率、I/O 效率和减少饥饿和内部竞争。</li><li>优化了 C Store，提高了随机读写的性能。</li><li>C Store 的核心功能已实现，包括数据读写、元数据索引、事务支持和背景任务等。</li><li>优化了性能，包括 FGC 缓存和 128 位逻辑块地址支持。</li></ul><p><strong>三、未来计划</strong></p><ul><li>推进性能改进，特别是多核支持下的性能。</li><li>优化异步消息传递，提高其可扩展性。</li><li>优化 C Store，提高其性能和可用性。</li><li>支持更复杂的 Scrub 功能。</li><li>支持动态 CPU 核心分配。</li><li>扩展测试套件，包括 RBD 镜像测试。</li></ul><p><strong>四、行动计划</strong></p><ul><li>Squid 项目成员将继续优化 Squid 和 Crimson，并推进未来计划。</li><li>Intel 团队将继续优化 C Store，并提高其性能和可用性。</li><li>Squid 项目成员将积极参与社区贡献，并推动 Squid 的发展。</li></ul><p><strong>五、其他事项</strong></p><ul><li>讨论了异步消息传递的性能问题，并探讨了可能的解决方案。</li><li>讨论了 C Store 的扩展性，并探讨了如何提高其性能。</li></ul><p><strong>总结</strong>：</p><p>本次会议回顾了 Squid 和 Crimson 的进展，并讨论了未来的计划。会议强调了性能优化和扩展性改进的重要性，并制定了具体的行动计划。</p>",18)])])}const d=t(r,[["render",n]]);export{C as __pageData,d as default};
